          VocabularyEntry("Geometric Progression", "Sequence advancing by a constant multiplier ratio r (T_n = ar^{n-1}).", "Compounding jump multiplying \\times r every step.", "Converges to S_\\infty = \\frac{a}{1-r} strictly when |r| < 1!"),
          VocabularyEntry("Identity Element (e)", "Element leaving any partner unchanged under operation ∗ (a ∗ e = a).", "Zero for addition; 1 for multiplication—depends on rule ∗!", "Solve a ∗ e = a explicitly—never assume e is 0 or 1."),
          VocabularyEntry("Inverse Element (a^{-1})", "Partner combining with a under ∗ to produce identity e (a ∗ a^{-1} = e).", "Undo button returning straight back to identity e.", "Must compute identity e FIRST before solving a ∗ a^{-1} = e!"),
