        sec3Body = "A GP decays to finite total S_\\infty = \\frac{a}{1 - r} ONLY if |r| < 1; if |r| \\ge 1, the sum diverges! For binary operation ∗: Commutative means a ∗ b = b ∗ a; Associative means (a ∗ b) ∗ c = a ∗ (b ∗ c); Identity solves x ∗ e = x.",
        sec3Formula = "T_n^{\\text{AP}} = a + (n-1)d   |   T_n^{\\text{GP}} = ar^{n-1}   |   S_\\infty = \\frac{a}{1-r} \\; (|r|<1)",
        sec3Tip = "Remember T_n = S_n - S_{n-1} connects any series sum formula back to its nth term!",
