        sec3Formula = "V_{\\text{cone}} = \\frac{1}{3}\\pi r^2 h   |   A_{\\text{cone, curved}} = \\pi r l   |   V_{\\text{sphere}} = \\frac{4}{3}\\pi r^3   |   r_{\\text{lat}} = R\\cos\\alpha",
        sec3Tip = "When computing latitude speed or distance between East & West longitudes, ADD angles (30°E + 15°W = 45°); same side SUBTRACT!",
        sec3Mech = "Because East and West lie on opposite sides of Greenwich 0°, spanning across 0° sums both angular offsets.",
        sec3Intel = "WAEC Paper 2 earth-geometry questions award generous marks for clean sphere meridian/parallel sketches.",
