        sec4Title = "4. Northern Grain Silos, Fuel Tankers & Bucket Frustums",
        sec4Body = "Steel fabricators in Kano and Kaduna build cylindrical grain silos topped with conical roofs: sheet-metal cost uses Curved Cylinder 2πrh + Cone πrl, whereas grain storage capacity sums πr²h_cyl + ⅓πr²h_cone.",
        sec4Tip = "Leave π intact until the final step when multiple solids combine—avoids cumulative rounding errors!",
        sec5Title = "5. Diameter-vs-Radius & Slant-vs-Height Check",
        sec5Body = "Read EVERY mensuration prompt for 'diameter' vs 'radius' (halve diameter IMMEDIATELY!) and verify open-top containers have ONLY ONE πr² base instead of 2πr²!",
        sec5Tip = "Total Surface Area of a CLOSED hemisphere is 2πr² (dome) + πr² (flat circle) = 3πr²!",
        misc1 = MisconceptionAnalysis("Sector radius R folded into a cone equals the cone's vertical height h.", "Both are heights of the diagram.", "Sector radius R folds along the SLANTED side l of the cone; vertical height h = √(l² − r²) is shorter!", "Label R → l first, then compute r_base and h."),
        misc2 = MisconceptionAnalysis("Total surface area of a solid hemisphere is 2πr².", "Half of sphere's 4πr².", "Slicing a solid ball exposes a flat circular cut face (+πr²), making CLOSED hemisphere TSA = 3πr²!", "Open bowl = 2πr²; Solid hemisphere = 3πr²."),
