        projModel = "Cone slant l = √(3²+4²) = 5 m. External metal TSA = π(3)² + 2π(3)(5) + π(3)(5) = 54π ≈ 169.6 m². Volume = π(9)(5) + ⅓π(9)(4) = 57π ≈ 179.1 m³ (179,100 litres).",
