      "math_11_trig_bearings" to spec(
        prereq = listOf("math_08_polygons_parallels (alternate & co-interior angles)", "Pythagoras"),
        dep = "Trig identities, Sine/Cosine rules, and 3-figure bearings feed directly into Physics vector resolution and Coordinate Calculus.",
        vocab = listOf(
          VocabularyEntry("CAST Quadrant Rule", "Signs of trig ratios: All (+ in Q1), Sin (+ in Q2), Tan (+ in Q3), Cos (+ in Q4).", "Positive sign map moving anticlockwise 0°→360°.", "sin(180°−θ)=sin θ; cos(180°−θ)=−cos θ!"),
          VocabularyEntry("Exact Special Angles", "30°, 45°, 60° sine/cosine/tangent built from 1-1-√2 and 1-√3-2 triangles.", "Calculator-free exact surd values demanded by JAMB.", "sin 30°=cos 60°=½; tan 45°=1; tan 60°=√3."),
          VocabularyEntry("3-Figure Bearing", "Angle measured CLOCKWISE from true North written in 3 digits (e.g., 045°).", "Compass navigation standard.", "Back bearing = Forward ± 180°!"),
          VocabularyEntry("Elevation vs Depression", "Upward look above horizontal vs downward look below horizontal.", "Eye-level angle between horizontal line and sightline.", "Equal by alternate Z-angles between horizontal eye lines!"),
        ),
        mech1 = "The fundamental Pythagorean identity sin²θ + cos²θ = 1 flows straight from x² + y² = 1 on a unit circle—giving immediate exact fractions from any single trig ratio without a calculator!",
        mech2 = "In non-right triangles, use SINE RULE when you hold an opposite angle-side pair (a/sin A = b/sin B); use COSINE RULE for SAS (two sides + trapped angle) or SSS (all three sides)!",
        intel1 = "JAMB tests calculator-free surd combinations (sin 60° cos 30° + tan 45°), obtuse triangle areas ½ab sin C, and 3-figure back bearings.",
        intel2 = "WAEC Paper 2 tests 2-leg ship/aircraft bearing journeys using North-line parallel geometry + Cosine Rule + Sine Rule.",
        recap1 = "Bearing rules: start from NORTH, sweep CLOCKWISE, write 3 digits.",
        recap2 = "SAS or SSS → Cosine Rule; Opposite Pair → Sine Rule.",
        sec3Title = "3. Sine Rule, Cosine Rule & 3-Figure Compass Sketches",
        sec3Body = "At EVERY turning point in a bearing problem, draw a clean vertical North arrow first! Extend or use co-interior/alternate parallel rules between North arrows to determine the internal triangle angle trapped between the two travel legs—NEVER plug raw compass bearings directly into Cosine Rule unless they already form the internal triangle angle.",
        sec3Formula = "\\frac{a}{\\sin A} = \\frac{b}{\\sin B}   |   a^2 = b^2 + c^2 - 2bc\\cos A   |   \\text{Area} = \\frac{1}{2}ab\\sin C",
        sec3Tip = "Check: if the angle between legs is obtuse (>90°), cos A is NEGATIVE—so −2bc cos A flips into ADDITION!",
        sec3Mech = "Subtracting a negative product turns + (−)(−) = + so obtuse triangles naturally stretch the opposite side longer than Pythagoras.",
        sec3Intel = "WAEC bearing graders deduct heavily when −2bc cos 120° stays subtracted instead of adding!",
        sec3Recap = "Draw North crosses at BOTH ends of every leg.",
        sec4Title = "4. Maritime Navigation Off Bonny & Aviation Flight Legs",
        sec4Body = "Coastal vessels leaving Port Harcourt harbour navigate multi-leg compass bearings; pilots compute wind-corrected headings and landing return bearings using Back Bearing = Forward Bearing ± 180° and Cosine Rule distance checks.",
        sec4Tip = "Angle of elevation from boat to lighthouse equals angle of depression from lighthouse top down to boat!",
        sec5Title = "5. Calculator Degree-Mode & Bearing Quadrant Check",
        sec5Body = "Make sure every bearing sketch checks quadrant sanity: 000°–090° (NE), 090°–180° (SE), 180°–270° (SW), 270°–360° (NW). Verify triangle side lengths satisfy the largest angle opposite the longest side!",
        sec5Tip = "Remember complementary trig pairs: sin θ = cos(90° − θ)!",
        misc1 = MisconceptionAnalysis("Angle of depression is measured downward from the vertical wall.", "Looks down along the tower.", "Both Elevation AND Depression are ALWAYS measured from the HORIZONTAL line!", "Draw horizontal eye-line first before measuring angle down."),
        misc2 = MisconceptionAnalysis("Cosine rule a² = b² + c² − 2bc cos A always subtracts 2bc cos A even at A = 120°.", "Sign printed in formula is minus.", "Because cos 120° = −0.5 is NEGATIVE, subtracting a negative adds +bc cleanly!", "Evaluate cos A with its CAST quadrant sign first."),
        guidedPrompt = "A cyclist rides 6 km on a bearing of 030°, then turns and rides 8 km on a bearing of 120°. Find his straight-line distance from start and bearing from start.",
        guidedHints = listOf(
          "Hint 1: Draw North arrows at start O and turn A. Co-interior South-from-A to North-at-O makes South-A bearing 210°.",
          "Hint 2: Turn leg leaves at 120°; internal angle at A = 210° − 120° = 90°!",
          "Hint 3: Pythagoras gives d = √(6² + 8²) = 10 km; tan θ = 8/6 → bearing = 030° + 53.1°.",
        ),
        guidedApproach = "Draw parallel North arrows → internal angle = 90° → Pythagoras + SOH-CAH-TOA + add initial bearing.",
        guidedSolution = "Internal ∠OAB = (180°+30°) − 120° = 90° (right triangle!). Distance OB = √(6²+8²) = 10.0 km. tan ∠AOB = 8/6 → 53.1° → Bearing of B from O = 030° + 53° = 083°.",
        projTitle = "Two-Leg Rescue Helicopter Flight Log",
        projScenario = "A rescue helicopter flies 40 km due North (000°), then 30 km on 060° to an offshore rig. Compute direct return distance & bearing back to base.",
        projStages = listOf("Sketch O→A (40 km N) and A→B (30 km at 060°).", "Find internal obtuse ∠OAB = 180° − 60° = 120°.", "Apply Cosine Rule with cos 120° = −0.5 and find return bearing."),
        projRubric = listOf("Uses ∠OAB = 120°.", "Computes √(1600 + 900 + 1200) = √3700 ≈ 60.8 km.", "Computes bearing B from O then flips ±180°."),
        projModel = "Internal ∠OAB = 120°. Distance OB = √(40²+30²−2(40)(30)(−0.5)) = √3700 ≈ 60.8 km. By Sine Rule, sin∠AOB = 30 sin 120° / 60.8 = 0.427 → 25.3° → B is 025° from O → Return bearing from B back to O = 025° + 180° = 205°.",
        cheatOverview = "SOH-CAH-TOA; Sine Rule pair; Cosine Rule SAS/SSS; Bearings Clockwise from North.",
        cheatLegend = listOf("sin²θ+cos²θ=1", "sin 30°=½", "cos 120°=−½", "Back = Fwd ± 180°"),
        cheatTraps = listOf("Measuring depression from vertical", "Forgetting −(−) flip in obtuse Cosine Rule", "Ignoring parallel North lines"),
        cheatMemory = "CAST: All-Students-Take-Chemistry; North Clockwise 3 Digits.",
      ),
      "math_12_coordinate_geometry" to spec(
