        mech2 = "Expanding (x − a)² + (y − b)² = r² produces −2ax − 2by + (a² + b² − r²), proving why centre (−g, −f) takes HALF the x, y coefficients with OPPOSITE sign!",
        intel1 = "JAMB tests perpendicular line through a given point, distance between points, and extracting circle centre & radius after dividing out a leading coefficient.",
        intel2 = "WAEC Paper 2 tests proving triangle type via distances/gradients and tangent equations to circles at point (x₁, y₁).",
        recap1 = "Parallel: m₂ = m₁; Perpendicular: m₂ = −1/m₁.",
        recap2 = "Divide 2x² + 2y²... by 2 FIRST before extracting (−g, −f) and √(g²+f²−c)!",
        sec3Title = "3. Ratio Division, Tangent to Circle & Distance Bounds",
        sec3Body = "Dividing segment AB in ratio m:n places P at ((nx₁+mx₂)/(m+n), (ny₁+my₂)/(m+n)). A tangent to circle centre C at boundary point P sits strictly perpendicular to radius CP (gradient m_tan = −1 / m_CP)!",
        sec3Formula = "m = \\frac{y_2-y_1}{x_2-x_1}   |   m_1 m_2 = -1   |   d = \\sqrt{(x_2-x_1)^2 + (y_2-y_1)^2}   |   r = \\sqrt{g^2+f^2-c}",
        sec3Tip = "Do NOT plug −x₁ directly into centre if circle starts with 3x² + 3y²—normalize coefficient to 1 FIRST!",
        sec3Mech = "Completing the square on x and y demands coefficient 1 on x² and y² so (x − a)² aligns cleanly.",
