        sec3Recap = "Normalize x² + y² to coefficient 1 → Halve & Negate for Centre.",
        sec4Title = "4. Lagos Estate Layout Grids & Delivery GPS Routing",
        sec4Body = "Urban surveyors laying perpendicular access streets off major avenues use m₁m₂ = −1 to check corner squareness cleanly on grid maps, while courier dispatch calculates straight-line Euclidean proximity √(Δx²+Δy²) to nearest riders.",
        sec4Tip = "Acute angle θ between two lines: tan θ = |(m₁ − m₂)/(1 + m₁m₂)|.",
        sec5Title = "5. Sign-Order & Perpendicular Bisector Verification",
        sec5Body = "Always verify gradient order consistency (y₂ − y₁)/(x₂ − x₁)—never flip x₁ − x₂ in the denominator while keeping y₂ − y₁ on top!",
        sec5Tip = "Perpendicular bisector uses BOTH Midpoint AND Negative-Reciprocal gradient!",
        misc1 = MisconceptionAnalysis("Centre of x² + y² − 6x + 4y − 12 = 0 is (−6, 4) or (6, −4).", "Reading coefficients directly without halving.", "2g = −6 → g = −3 → centre x = −g = +3; 2f = +4 → f = +2 → y = −2. Centre is (3, −2)!", "Halve AND Negate coefficients of x and y."),
        misc2 = MisconceptionAnalysis("A line perpendicular to y = 3x + 2 has gradient −3.", "Forgetting reciprocal flip.", "Perpendicular flips BOTH sign and fraction: −1/3 (check 3 × (−1/3) = −1).", "Negative RECIPROCAL, not just negative."),
        guidedPrompt = "Find the centre and radius of the circle 2x² + 2y² − 8x + 12y − 6 = 0, and find the equation of the line perpendicular to 3x + 2y = 5 passing through that centre.",
        guidedHints = listOf(
          "Hint 1: Divide the entire circle equation by 2 first: x² + y² − 4x + 6y − 3 = 0.",
          "Hint 2: Halve & negate: Centre = (2, −3); Radius = √(2² + (−3)² − (−3)) = √16 = 4.",
          "Hint 3: 3x + 2y = 5 → y = −(3/2)x + 5/2 (m = −3/2) → perpendicular m₂ = +2/3 through (2, −3).",
